<script setup lang="ts">
import { reactive } from 'vue'
import { Head, Link, router } from '@inertiajs/vue3'
import { route } from 'ziggy-js'
import { usePermissions } from '../../../composables/usePermissions'
interface Rol{id:string;name:string}interface Usuario{id:string;name:string;email:string;activo:boolean;roles:Rol[];created_at:string}interface Pagina<T>{data:T[];current_page:number;last_page:number;prev_page_url:string|null;next_page_url:string|null;total:number}
const props=defineProps<{usuarios:Pagina<Usuario>;roles:Rol[];filtros:{buscar:string;estado?:string;rol?:string};usuarioActualId:string}>();const{can}=usePermissions();const filtros=reactive({buscar:props.filtros.buscar||'',estado:props.filtros.estado||'todos',rol:props.filtros.rol||'todos'})
function filtrar(){router.get(route('usuarios.index'),{buscar:filtros.buscar||undefined,estado:filtros.estado==='todos'?undefined:filtros.estado,rol:filtros.rol==='todos'?undefined:filtros.rol},{preserveState:true,replace:true})}
function estado(u:Usuario){const activo=!u.activo;if(!confirm(`¿${activo?'Activar':'Desactivar'} la cuenta de ${u.name}?`))return;router.patch(route('usuarios.estado',u.id),{activo},{preserveScroll:true})}
</script>
<template><Head title="Usuarios"/><UDashboardPanel><template #header><UDashboardNavbar title="Usuarios y accesos"><template #leading><UDashboardSidebarCollapse/></template><template #right><Link v-if="can('usuarios.crear')" :href="route('usuarios.create')"><UButton label="Nuevo usuario" icon="i-lucide-user-plus"/></Link></template></UDashboardNavbar></template><template #body><div class="space-y-6"><div class="grid gap-3 sm:grid-cols-3"><UCard><p class="text-sm text-muted">Usuarios</p><p class="text-3xl font-semibold">{{usuarios.total}}</p></UCard><UCard><p class="text-sm text-muted">Roles disponibles</p><p class="text-3xl font-semibold">{{roles.length}}</p></UCard><UCard><p class="text-sm text-muted">Administración</p><p class="mt-2 text-sm">Sin eliminación física de cuentas</p></UCard></div><form class="grid gap-3 md:grid-cols-[minmax(14rem,1fr)_12rem_14rem_auto]" @submit.prevent="filtrar"><UInput v-model="filtros.buscar" icon="i-lucide-search" placeholder="Nombre o correo"/><USelect v-model="filtros.estado" :items="[{label:'Todos los estados',value:'todos'},{label:'Activos',value:'activo'},{label:'Inactivos',value:'inactivo'}]"/><USelect v-model="filtros.rol" :items="[{label:'Todos los roles',value:'todos'},...roles.map(r=>({label:r.name,value:r.name}))]"/><UButton type="submit" label="Filtrar" icon="i-lucide-list-filter"/></form><div class="overflow-x-auto rounded-lg border border-default"><table class="w-full min-w-[760px] text-sm"><thead class="bg-elevated/60 text-left"><tr><th class="p-3">Usuario</th><th class="p-3">Roles</th><th class="p-3">Estado</th><th class="p-3">Creado</th><th class="p-3 text-right">Acciones</th></tr></thead><tbody><tr v-for="u in usuarios.data" :key="u.id" class="border-t border-default"><td class="p-3"><p class="font-medium">{{u.name}} <UBadge v-if="u.id===usuarioActualId" size="xs" color="neutral">Tú</UBadge></p><p class="text-muted">{{u.email}}</p></td><td class="p-3"><div class="flex flex-wrap gap-1"><UBadge v-for="r in u.roles" :key="r.id" color="primary" variant="subtle">{{r.name}}</UBadge><span v-if="!u.roles.length" class="text-muted">Sin rol</span></div></td><td class="p-3"><UBadge :color="u.activo?'success':'neutral'">{{u.activo?'Activo':'Inactivo'}}</UBadge></td><td class="p-3 text-muted">{{new Date(u.created_at).toLocaleDateString('es-CO')}}</td><td class="p-3 text-right"><Link v-if="can('usuarios.editar')" :href="route('usuarios.edit',u.id)"><UButton size="sm" color="neutral" variant="ghost" icon="i-lucide-pencil" aria-label="Editar usuario"/></Link><UButton v-if="can('usuarios.desactivar')&&u.id!==usuarioActualId" size="sm" color="neutral" variant="ghost" :icon="u.activo?'i-lucide-user-x':'i-lucide-user-check'" aria-label="Cambiar estado" @click="estado(u)"/></td></tr><tr v-if="!usuarios.data.length"><td colspan="5" class="p-10 text-center text-muted">No hay usuarios que coincidan con los filtros.</td></tr></tbody></table></div><div class="flex flex-col items-center justify-between gap-3 sm:flex-row"><p class="text-sm text-muted">Página {{usuarios.current_page}} de {{usuarios.last_page}} · {{usuarios.total}} registros</p><div class="flex gap-2"><UButton label="Anterior" color="neutral" variant="outline" :disabled="!usuarios.prev_page_url" @click="usuarios.prev_page_url&&router.visit(usuarios.prev_page_url)"/><UButton label="Siguiente" color="neutral" variant="outline" :disabled="!usuarios.next_page_url" @click="usuarios.next_page_url&&router.visit(usuarios.next_page_url)"/></div></div></div></template></UDashboardPanel></template>
